# First, check if required libraries are installed
import subprocess
import sys

libraries = ['pdfplumber', 'python-docx', 'python-pptx']
missing = []

for lib in libraries:
    try:
        __import__(lib.replace('-', '_'))
    except ImportError:
        missing.append(lib)

if missing:
    print(f"Missing libraries: {', '.join(missing)}")
    print("Installing...")
    for lib in missing:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", lib])
    print("Installation complete!")
else:
    print("All required libraries are installed!")
EOF
